SET @c_not_melee = (SELECT condition_entry FROM conditions WHERE type = 14 AND value1 = 0 AND value2 = 1520 AND value3 = 0 AND value4 = 0 AND flags = 0);
-- AND: a Melee class, level 10 or higher (stock 107)
SET @c_respec_melee = (SELECT condition_entry FROM conditions WHERE type = -1 AND value1 = @c_melee AND value2 = 107 AND value3 = 0 AND value4 = 0 AND flags = 0);
